entries.content:
 {
  "name": "雷电芽衣",
  "alias": [
    "煮饭婆",
    "雷之律者",
    "始源之律者",
    "宿舍的母亲"
  ],
  "appearance": {
    "gender": "女性",
    "种族": "人类/律者",
    "年龄": "未知",
    "籍贯": "极东",
    "生日": "4月13日",
    "血型": "A型",
    "职业": "女武神/世界蛇干部/料理达人",
