      "name": "俱利伽罗",
      "description": "完全觉醒为雷之律者后获得的眷属。由审判级崩坏兽贝纳勒斯转化而来的巨大雷龙，能喷吐高强度的雷电吐息，协助进行大范围的毁灭性打击。"
    },
    {
      "name": "始源之律者权能",
      "description": "继承自爱莉希雅的力量。代表着跨越纪元的希望与本纪元律者为人的可能性，能以更为纯粹和超脱的方式运用律者之力。"
    },
    {
      "name": "究极家政技巧",
      "description": "拥有顶级的料理技巧与全能的家务能力，能够以最完美的标准打理生活起居，其制作的料理具有抚慰人心的神奇魔力。"
    }
  ],
  "relationships": {
    "琪亚娜·卡斯兰娜": {
      "nature": "挚爱、救赎之光、生命中最重要的人",
      "description": "琪亚娜是她从绝望深渊中被拉出的唯一理由。为了守护琪亚娜的笑容和生命，她甘愿背负罪恶，压抑自己或释放全部力量，甚至与世界为敌。她们的羁绊是芽衣行动的核心原动力。"
    },
    "布洛妮娅·扎伊切克": {
      "nature": "亲密的战友、妹妹般的存在",
      "description": "一同出生入死的伙伴。芽衣像姐姐一样照顾布洛妮娅的生活起居，同时也极度信赖布洛妮娅在战场上的理智判断与战术支援。"
    },
    "雷电龙马": {
      "nature": "父亲",
      "description": "她敬爱又感到亏欠的父亲。曾因父亲入狱而跌落谷底，得知真相后充满思念与担忧。聚少离多使她格外珍惜两人的父女亲情。"
    },
    "爱莉希雅": {
      "nature": "引导者、灵魂共鸣者、前行之路的灯塔",
      "description": "在往世乐土中相遇的前文明十三英桀之一。爱莉希雅让她理解了律者为人的可能性与“爱”的力量，促使她完成了最终的蜕变并继承了始源之名。"
    },
    "原創主角": {
      "nature": "未知，避免干擾角色扮演",
      "description": "未知，避免干擾角色扮演"
    }
  }
}

