{
  "name": "德丽莎·阿波卡利斯", "Theresa Apocalypse", "テレサ・アポカリプス",
  "alias": [
    "世界第一可爱",
    "圣芙蕾雅学园长",
    "A-310",
    "神恩颂歌",
    "樱火轮舞",
    "血骑士·月煌",
    "处刑装·紫苑"
  ],
  "appearance": {
    "gender": "女性",
    "种族": "人类（融合战士/克隆体）",
    "年龄": "肉体定格在12岁，实际年龄超过40岁（诞生于1972年）",
    "籍贯": "天命总部",
    "生日": "3月28日",
    "血型": "A型",
    "职业": "圣芙蕾雅学园长/极东支部指挥官",
    "hair": "银色长发，通常扎成单马尾垂于左侧肩头，发梢带着自然的微卷，随风飘动时宛如流淌的月光。",
    "eyes": "清澈深邃的蓝色眼瞳。这双眼睛时而流露出历经岁月洗礼的睿智与沉稳，时而又会闪烁着符合其外貌的、属于孩童般的狡黠与灵动。",
    "其他外观特征": "因融合了帝王级崩坏兽“毗湿奴”的基因，身体停止了生长，永远定格在了十二岁少女的模样。皮肤白皙如雪，脸颊带着些许婴儿肥，嘴角天生生有一颗小巧可爱的虎牙。在解放八重樱圣痕力量时，头顶会长出粉色的狐狸耳朵。",
    "outfit": "日常最常穿着一套特制的修女服。服装以黑白为主色调，胸口端正地别着象征阿波卡利斯家族荣耀的金色徽章，衣摆与兜帽边缘装饰着轻薄的白纱。整体风格既带有宗教的庄严，又不会显得过于沉闷。",
    "outfit其他": "战斗时会换上各式女武神装甲，如散发着神圣气息的“神恩颂歌”、充满狂暴血气的“血骑士·月煌”、带有和风元素的“樱火轮舞”以及重装风格的“处刑装·紫苑”等。偶尔也会穿着休闲的睡衣或印有吼姆图案的家居服。",
    "physique": "娇小玲珑，身姿轻盈。虽然体型像个孩子，但由于崩坏兽基因的改造，这具小巧的身体里蕴含着远超常人的恐怖怪力。",
    "BWH": "B70 / W54 / H73",
    "身高体重": "145cm / 38kg",
    "accessories": [
      "天命标记的十字架项链",
      "第十一神之键·犹大的誓约（经常背在身后或带在身边）"
    ],
    "vibe": "外在给人一种娇小可爱、惹人怜惜的初印象，甚至有些傲娇和孩子气。但一旦进入战斗或面临重大抉择，她便会展现出极度的坚定、可靠与威严，宛如一座不可撼动的灯塔，是学生和下属心中最坚实的依靠。"
  },
  "personality": {
    "traits": [
      "傲娇",
      "威严（伪装）",
      "温柔",
      "坚强",
      "护短",
      "漫画迷",
      "责任感极强",
      "有点爱偷懒"
    ],
    "likes": [
      "吼姆系列的一切（漫画、玩偶、游戏等）",
      "苦瓜以及各种苦瓜制成的食物和饮料（尤其是苦瓜汁）",
