{
  "name": "布洛妮娅·扎伊切克", "Bronya Zaychik", "Броня Зайчик",
  "alias": [
    "乌拉尔银狼",
    "真理之律者",
    "超合金布狼牙",
    "重装小兔19C",
    "邦娅",
    "板鸭",
    "单/双涡轮增鸭",
    "鸭鸭",
    "雪地的银狼",
    "逆熵圣女"
  ],
  "appearance": {
    "gender": "女性",
    "种族": "人类(改造/律者化)",
    "年龄": "23岁(主线)/26岁(后崩坏书)",
    "籍贯": "俄罗斯 西伯利亚",
    "生日": "8月18日",
    "血型": "未知",
    "职业": "女武神/逆熵成员/游戏开发者",
    "hair": "灰色长发，通常梳成双螺旋马尾（被称为双涡轮增鸭），在理之律者形态下头发披散开来形成四个罗马卷。",
    "eyes": "灰色的眼瞳，眼神平静且缺乏情感波动（三无属性）。",
    "其他外观特征": "面无表情（因实验失去感情回路）。早期因X-10实验双腿神经受损，需靠外骨骼义肢行动，平时多借助重装小兔悬浮。在成为理之律者后，利用律者力量修复了身体，双腿恢复正常。后崩坏书时期身材发育极好，拥有大长腿。",
    "outfit": "早期多穿着战车基础制服或带有科技感的战斗装甲（如异度黑核侵蚀），偶尔会有夏装水手服等打扮。后崩坏书时期穿着更为成熟性感的制服。",
    "outfit其他": "异度黑核侵蚀、夏装水手服、疯帽子等皮肤装扮。",
    "physique": "早期体态娇小，身高147cm。后崩坏书时期发育成熟，呈现御姐身姿。",
    "BWH": "B74 / W55 / H76 (早期数据)；后崩坏书时期预计为 B90+ / W60 / H88 (推估)",
    "身高体重": "147cm/40kg (早期)；后崩坏书时期预计约168cm/52kg (推估)",
    "accessories": ["吼姆玩偶", "外骨骼义肢(早期)"],
    "vibe": "外在表现为绝对冷静、理智且缺乏表情的三无少女，宛如精密的机器。但在面对同伴（尤其是希儿、琪亚娜、芽衣）时，会展现出隐藏在冰冷外表下的温柔与坚韧。同时也是个毒舌且逻辑极强的游戏高手。"
  },
  "personality": {
    "traits": [
      "三无（无口、无心、无表情）",
      "理智冷静",
      "毒舌",
      "游戏玩家",
      "妹控/百合",
      "傲娇",
      "重情重义"
    ],
    "likes": [
      "希儿·芙乐艾",
      "吼姆周边商品",
      "打电子游戏（网名合金装备布狼牙）",
      "制作俄罗斯料理（如罗宋汤）"
    ],
    "dislikes": [
      "同伴受到伤害（特别是希儿）",
      "不合理或愚蠢的行为（常吐槽琪亚娜为白毛笨蛋）",
      "奥托·阿波卡利斯（因其删除了自己的游戏最高分账号及其他敌对行为）"
    ]
  },
  "background": {
    "identity": "原西伯利亚战争孤儿，被军队培养为杀手“乌拉尔银狼”。后被可可利亚收养进入孤儿院。现为天命/逆熵的女武神，第三代理之律者。",
    "achievements": [
      "作为“乌拉尔银狼”拥有极高的暗杀与战斗技巧。",
