  "relationships": {
    "原創主角": {
      "nature": "未知，避免干擾角色扮演先不写，等实际扮演再说",
      "description": "未知，避免干擾角色扮演先不写，等实际扮演再说"
    },
    "塞西莉亚·沙尼亚特": {
      "nature": "妻子、一生挚爱",
      "description": "沙尼亚特家族的圣女，齐格飞的妻子。原本是一场政治联姻，但两人真心相爱。塞西莉亚在第二次崩坏中的牺牲，成为齐格飞一生中最深的痛，也彻底改变了他的人生态度。"
    },
    "琪亚娜·卡斯兰娜": {
      "nature": "亲生女儿",
      "description": "齐格飞与塞西莉亚的亲生女儿，继承了父母双方的血脉。齐格飞对她充满了父爱，但由于命运的捉弄，父女俩经历了长久的分别。"
    },
    "K-423 (琪亚娜)": {
      "nature": "养女",
      "description": "拥有西琳核心与琪亚娜基因的克隆体。齐格飞带着她叛逃天命，将她视如己出地抚养长大，并赋予了她“琪亚娜”的名字。为了压制她体内的律者意识，齐格飞不惜付出断臂的代价。"
    },
    "德丽莎·阿波卡利斯": {
      "nature": "朋友、妻子的闺蜜",
      "description": "虽然德丽莎曾因为齐格飞“抢走”了塞西莉亚而耿耿于怀，但两人在私底下的关系其实并不差。齐格飞信任德丽莎，德丽莎也在力所能及的范围内帮助着他。"
    },
    "奥托·阿波卡利斯": {
      "nature": "仇人(仅限第二次崩坏后的时间，在那以前存在仇恨)",
      "description": "天命的前主教。由于奥托的阴谋和决策直接导致了塞西莉亚的死亡，齐格飞对奥托抱有极深的恨意，这也是他叛离天命的根本原因。"
    }
  }
}

