    "胆小鬼/爱哭鬼/透明人 (杏称)",
    "量子幽灵",
    "深海少女",
    "黑希",
    "黑希侠/黑犀侠",
    "希尔",
    "10%女士",
    "死生之律者",
    "高塔贤者"
  ],
  "appearance": {
    "gender": "女性",
    "种族": "人类/圣痕觉醒者/律者",
