      "nature": "前文明同僚、友人、被二创的对象",
      "description": "同为火种计划的执行者。丹朱觉得符华过于古板无趣，便热衷于将符华的事迹改编成传奇故事，并在捏制赤鸢仙人的泥人时，故意将其胸部等特征设计得十分突出。符华对丹朱的“亚文化”爱好常常感到无奈，但三人之间有着深厚的战友情谊。"
    },
    "姬麟 (姬轩辕)": {
      "nature": "选中的传承者、新文明的希望",
      "description": "丹朱与苍玄在新文明寻找到了拥有极高崩坏能适应性的少女姬麟，丹朱亲手将第十神之键“轩辕剑”交予她。姬麟是她们计划的具象化，也是她们对抗崩坏的重要战力。"
    },
    "梅比乌斯": {
      "nature": "前文明的上级/导师",
      "description": "在逐火之蛾时期，丹朱与苍玄曾是梅比乌斯实验室的研究员。梅比乌斯的疯狂与智慧对她们产生了深远的影响。"
    },
    "克莱茵": {
      "nature": "前文明的师姐",
      "description": "同在梅比乌斯手下工作，克莱茵是她们的前辈与师姐，彼此之间有着科研人员的默契。"
    }
  }
}

