      "nature": "前文明同僚、友人、“债务人”",
      "description": "前文明的同僚，同时也是苍玄眼中的“债务人”。苍玄对符华非常了解，甚至连她上万年的生活成本都计算得一清二楚，经常拿抚养费的事情调侃她，展现了两人深厚且独特的羁绊。"
    },
    "梅比乌斯": {
      "nature": "前文明上级",
      "description": "在逐火之蛾时期的上级。虽然资料不多，但作为前文明的科学家，苍玄的工作或多或少受其影响。"
    },
    "克莱茵": {
      "nature": "前文明师姐",
      "description": "在逐火之蛾时期的师姐。克莱茵深知苍玄与丹朱这对活宝的本性。"
    }
  }
}

