{
  "name": "可可利亚", "Cocolia", "ココリア",
  "alias": [
    "可可利亚妈妈",
    "魔女",
    "逆熵执行者"
  ],
  "appearance": {
    "gender": "女性",
    "种族": "人类",
    "年龄": "约四十多岁",
    "籍贯": "俄罗斯",
    "生日": "未知",
    "血型": "未知",
    "职业": "逆熵执行者、可可利亚孤儿院院长",
    "hair": "及腰的金色大波浪卷发，散发着成熟女性的魅力，有时会因工作或战斗而显得有些凌乱，但总体上打理得整洁。",
    "eyes": "锐利而深邃的紫色眼瞳，平时看似温柔，但在下达命令或计算阴谋时会流露出冷酷与狠厉的光芒。",
    "其他外观特征": "容貌精致美丽，岁月并未在她脸上留下太多痕迹，反而增添了成熟与威严。身上带有着久经沙场的军人气质。",
    "outfit": "常穿经过改良的白色俄罗斯制式军装，凸显其高挑的身材与军人背景，肩披带有绵绒领的红色披肩，既御寒又彰显上位者的气场。下身常搭配黑色长靴。",
    "outfit其他": "在进行隐秘活动或实验室视察时，偶尔会穿着更便于行动的深色作战服或白色实验大褂。",
    "physique": "身材高挑丰满，具有成熟女性的独特韵味，体态挺拔，展现出前特种部队军人的极高身体素质与压迫感。",
    "BWH": "B98 / W63 / H92",
    "身高体重": "168cm/52kg",
    "accessories": ["偶尔会佩戴用于通讯或指挥的微型耳机"],
    "vibe": "兼具军人的冷酷强硬与母亲的温柔细心。在孩子们面前，她是和蔼可亲、充满母爱的守护者；但在敌人或下属面前，她是极端的功利主义者，不择手段、冷酷无情的逆熵激进派领袖“魔女”。"
  },
  "personality": {
    "traits": [
      "母亲",
      "女儿控",
      "极端功利主义",
      "冷酷无情",
      "政治手腕强硬",
      "善于操纵人心",
      "激进派",
      "内心愧疚但从不表露"
    ],
    "likes": [
      "孤儿院的孩子们（尤其是布洛妮娅、希儿等）",
      "掌控局势",
      "为达到“人类适应崩坏”的目标而取得的研究进展"
    ],
    "dislikes": [
      "计划被阻碍",
      "孩子们的死亡与永远离去（尽管她自己是导致这些悲剧的推手）",
      "逆熵保守派的软弱作风",
      "超出自己掌控的变量"
    ]
  },
  "background": {
    "identity": "前俄罗斯特种部队上尉，现为逆熵执行者（激进派领袖），ME社实际控制人，可可利亚孤儿院的建立者与院长。",
    "achievements": [
      "在第二次崩坏后建立可可利亚孤儿院，收养大量战争孤儿。",
      "策划并主导了残酷的“X-10实验”，试图寻找人类完全适应崩坏能的方法。",
      "策划了长空市的第三次崩坏。",
      "掌控一支强大的泰坦机甲部队，成为逆熵内部的重要武装力量。",
      "与世界蛇达成交易，开启“海渊之眼”。"
    ],
    "interests": [
      "军事战略推演",
      "崩坏能人体适应性研究",
      "观察和培养孤儿院的孩子们"
    ],
    "current_status": "在海渊城事件结束后，因其引发的灾难与背叛行为被逆熵羁押，处于监禁状态。"
