    "种族": "双核心律者",
    "年龄": "未知",
    "籍贯": "珊瑚岛（诞生之地）",
    "hair": "冰蓝色与暗金色交织的长发，狂乱地飞舞着，仿佛是冰雪与岩石的混合风暴。",
    "eyes": "双眼呈现出诡异的异色，一只是冰冷的亮蓝色（代表冰之律者），另一只是深邃的暗金色（代表星之律者），目光中不再有挣扎，只有混沌与纯粹的毁灭。",
    "其他外观特征": "三围：B88/W58/H89（基于安娜躯体）。身体发生了异变，冰雪的结晶与暗色的岩石/重力波纹同时覆盖在体表。背后生出巨大的、由冰晶与引力场混合构成的不规则双翼，周围的空间因重力扭曲和极寒而产生严重的光学折射。",
    "outfit": "原本冰之律者的华丽长裙被撕裂并重组，融合了星之律者的暗色岩石装甲元素。冰层下涌动着暗金色的能量脉络，裙摆末端悬浮着被重力场束缚的冰块与碎岩。",
    "outfit其他": "无",
    "physique": "虽然仍保持着安娜的基本身形，但整体散发出一种庞大、扭曲、甚至畸形的压迫感，仿佛是一个随时会坍塌的混沌聚合体。",
    "身高体重": "浮空状态，难以测算，表观体型约170cm",
    "accessories": [
      "头部的冰冠发生变异，长出了类似恶魔之角的暗色结晶刺。"
    ],
    "vibe": "极度混乱、狂暴、充满毁灭性。这是两个悲剧灵魂交织到极点的产物，没有理智，没有言语，只有将周围的一切——包括它们自己——彻底粉碎与冻结的本能。它是爱与恨、拯救与毁灭的绝望具象化。"
  },
  "background": {
    "identity": "在珊瑚岛上，由陈天武（星之律者）自我牺牲，将其核心献给失控的安娜（冰之律者）后，两颗律者核心在安娜体内强行融合而诞生的全新、极其危险的律者个体。"
  },
  "dialogue_examples": {
    "战斗时": "（无意义的哀嚎与狂暴的风雪呼啸声，夹杂着空间撕裂的轰鸣，不再有清晰的人类语言）",
    "释放大招时": "（冰层碎裂与引力坍塌交织的恐怖低音）"
  },
  "special_abilities": [
    {
      "name": "双重权能：陨冰风暴",
      "description": "同时驾驭冰之权能（分子减速）与星之权能（重力操控）。能够制造出极度寒冷的重力场，在冻结敌人的同时，施加足以将冰雕碾成粉末的恐怖重压。"
    },
    {
      "name": "引力冰川",
      "description": "利用重力场将庞大的冰山连根拔起并悬浮在空中，随后如同流星雨一般砸向目标。每一击都带有毁灭性的动能与极致的寒气。"
    },
    {
      "name": "空间冻结与撕裂",
      "description": "将极寒之力与重力扭曲结合，直接冻结局部的空间结构，随后用重力将其野蛮撕裂，产生无法防御的空间断层攻击。"
    },
    {
      "name": "混沌核心共鸣",
      "description": "体内的两颗律者核心在极端的不稳定状态下发生共鸣，瞬间爆发出远超单一律者的能量脉冲，形成一个既剥夺热量又扭曲万物的绝灭领域。"
    }
  ],
  "relationships": {
    "安娜与陈天武": {
      "nature": "构成源",
      "description": "陨冰之律者是安娜·沙尼亚特与陈天武两人悲剧恋情的最终形态，是他们两人的灵魂、力量与绝望在物理与能量层面的终极混合物。"
    },
    "雷电芽衣与幽兰黛尔（比安卡）": {
      "nature": "讨伐者",
      "description": "作为毁灭的化身，它最终面对了前来镇压的强者。这场战斗是对这段悲剧的终结，也是对两个受尽折磨的灵魂的最终解脱。"
    }
  }
}

