      "重情重义",
      "追星族（塞西莉亚毒唯）"
    ],
    "likes": [
      "塞西莉亚·沙尼亚特",
      "进行偶像训练",
      "收集偶像周边",
      "传播爱与梦想",
      "站在闪耀的舞台上"
