      "description": "普朗克最珍爱的“丽瑟尔宝贝”。自爱因斯坦8岁起，普朗克便以导师与监护人的身份陪伴她，是爱因斯坦生命中近似母亲的关键存在。两人之间有着只有彼此才能完美应对玩笑的独特默契。"
    },
    "芙蕾德莉卡·尼古拉·特斯拉": {
      "nature": "学生、同伴、捉弄对象",
      "description": "被普朗克“捡”回来的天才。普朗克非常欣赏她的才华，经常以恶作剧（如骗她吃小牛睾丸）来捉弄她。尽管特斯拉常被气得叫她“老太婆”，但普朗克毫不在意，视其为重要的学生与中坚力量。"
    },
    "埃尔温·蕾安娜·薛定谔": {
      "nature": "得力助手、学生",
      "description": "普朗克非常依赖的助理，但也是常被普朗克吐槽的“煞风景的学生”。薛定谔过于理性的“扑克脸”发言常常让普朗克感到无奈。"
    },
    "瓦尔特·乔伊斯": {
      "nature": "初代盟主、捉弄对象",
      "description": "普朗克尊敬并追随的初代盟主。初次见面时，普朗克就用极其恶劣且顽皮的连串称呼（宠物、奴隶等）误认他，展现了她对谁都能恶作剧的性格。"
    },
    "南希·爱迪生": {
      "nature": "合作者、被掩护者",
      "description": "天命北美支部的真正领导者。普朗克利用自己的社交手腕，在台前扮演“润滑剂”与名义负责人，为爱迪生创造了在幕后运筹帷幄的空间。"
    },
    "卡尔·古斯塔夫": {
      "nature": "表亲",
      "description": "普朗克的表亲，正是他将年幼的爱因斯坦托付给了普朗克，促成了这段深厚的师徒缘分。"
    }
  }
}

