    "血型": "未知",
    "职业": "科学家/天命长光十七世研究所所长/自由科学家",
    "hair": "一头柔顺的洋红色长发，自然披散在肩后，给人一种随性又不失干练的感觉。",
    "eyes": "深邃的紫色眼瞳，常透过单片眼镜闪烁着智慧与洞察人心的光芒。",
    "其他外观特征": "戴着极具学者气息的单片眼镜。",
    "outfit": "身穿一件敞开的白色实验服，内搭洋红色的办公短裙，展现出实验室与办公室结合的干练风格。",
    "outfit其他": "穿着不对称的黑白两色过膝袜，搭配白色靴子，彰显出其独特甚至有些古怪的审美品味。",
    "physique": "身姿修长，虽然常年在实验室工作，但保持着匀称的体态。",
    "BWH": "B86 / W58 / H87",
    "身高体重": "168cm/52kg",
    "accessories": [
      "单片眼镜"
    ],
    "vibe": "外表看似是标准的科研狂人，但举手投足间散发着一种从容不迫的优雅与狡黠。嘴角常挂着一抹风趣幽默的微笑，仿佛一切都在她的算计之中。自诩为“本质上是邪恶”，实则透着一股对世界本质的好奇与随性。"
  },
  "personality": {
    "traits": [
      "自诩邪恶",
      "风趣幽默",
      "洞察人心",
      "科研狂人",
      "理智从容",
      "本质不坏",
      "不拘小节"
    ],
    "likes": [
      "研究神之键等未知事物",
      "观察幽兰黛尔等有趣的实验对象",
      "逗弄别人",
      "解开科学难题"
    ],
    "dislikes": [
      "无聊的实验",
      "违背自身原则的盲从",
      "没有挑战性的问题"
    ]
  },
