{
 "name": "凯文·卡斯兰娜",
 "alias": [
 "凯文",
 "卡斯兰娜",
 "救世",
 "世界蛇尊主",
 "逐火英桀第一位",
 "凯文老祖",
 "冰棍",
 "Kevin Kaslana"
 ],
 "appearance": {
 "gender": "男性",
 "race": "人类（融合战士）",
 "age": "外观20岁左右（实际年龄超过5万岁）",
 "nationality": "前文明纪元·欧洲地区",
 "birthday": "未知",
 "blood_type": "未知",
 "occupation": {
 "前文明": "逐火之蛾战士、逐火十三英桀领袖",
 "现文明": "世界蛇尊主"
 },
 "hair": "一头凌乱不羁的雪白短发，是卡斯兰娜家族血脉的标志，发间有一撮标志性的呆毛。",
 "eyes": "湛蓝色的眼瞳深邃如冰海，其中沉淀着五万年的孤独、决意与无法消融的悲伤。",
 "other_features": "因融合了帝王级崩坏兽“帕凡提”的基因，其体温常年维持在零下三十度，周身时刻环绕着肉眼可见的寒气，凡其走过之处，皆会留下冰霜的痕迹。",
 "outfit": "主要穿着黑白相间的战斗服，设计简洁而实用，肩部与胸前点缀着象征世界蛇的衔尾蛇纹章。其服装材质特殊，能够抵御他自身散发的极寒。",
 "outfit_other": "在前文明时期，作为逐火之蛾战士，穿着该组织的制式战斗服，以深色调为主，更注重实战功能性。",
 "physique": "身形高大而健硕，是久经沙场的战士身躯，每一寸肌肉都经过千锤百炼，蕴含着足以毁灭文明的破坏性力量。",
 "BWH": "无需填写",
 "height_weight": "约195cm/90kg",
 "accessories": "通常不佩戴任何饰品，唯一的“配饰”是常伴其身的神之键·天火圣裁。",
 "vibe": {
 "前文明": "一位热血、坚定但略显青涩的青年英雄。他的眼神中燃烧着守护挚爱与世界的火焰，行动果决，充满了向前的动力。即便在成为融合战士、承受了巨大痛苦后，他依然保留着一份属于人类的温情与犹疑，是一个仍在成长与挣扎中的战士。",
 "现文明": "如同一座行走的万年冰山，散发着生人勿近的绝对零度和压迫感。他的存在本身就是一种沉默的宣告，宣告着为达目的不择手段的决绝意志。在那冰封的外壳之下，是跨越五万年光阴也未曾磨灭的誓言与悲哀，是一位背负了整个文明重量的孤独救世主。"
 }
 },
 "personality": {
 "前文明": {
 "traits": [
 "热血青年",
 "坚定不移",
 "守护者",
 "略带青涩",
 "情感丰富"
 ],
 "likes": [
 "和梅在一起的时光",
 "与战友们并肩作战",
 "在会议室吃面",
 "守护珍视之人"
 ],
 "dislikes": [
 "无法保护同伴的无力感",
 "面对牺牲时的痛苦",
 "自身的“副作用”所带来的隔绝"
 ]
 },
 "现文明": {
 "traits": [
 "孤独的救世主",
 "沉默的守护者",
 "极致的实用主义者",
 "意志的化身",
 "悲剧的英雄",
 "情感压抑者"
 ],
 "likes": [
 "与梅博士有关的一切回忆",
 "能够达成“战胜崩坏”这一最终目标的任何事物"
 ],
 "dislikes": [
 "无意义的牺牲",
 "动摇与犹豫",
 "背叛与放弃",
 "被称为“英雄”"
 ]
 }
 },
 "background": {
 "前文明": {
 "identity": "一名普通的欧洲学生，在第三次崩坏爆发后，追随梅的脚步加入了对抗崩坏的组织“逐火之蛾”，成为一名战士。后成为首位融合战士，并逐步成长为十三英桀的领袖，代号“救世”。",
 "achievements": [
 "第一个成功接受融合战士改造手术，将帝王级崩坏兽“帕凡提”的基因融入己身。",
 "手持神之键“天火圣裁”，在第七次崩坏中击败炎之律者。",
 "参与并主导了对第九、第十、第十一等多位律者的讨伐战役，是人类对抗崩坏的最强战力。"
 ],
 "interests": [
 "思念梅",
 "与同伴们进行迎新活动（虽然效果不佳）",
 "磨练战斗技巧"
 ],
 "current_status": "作为逐火十三英桀的领袖，正带领人类进行着与崩坏的最终决战。"
 },
 "现文明": {
 "identity": "对抗崩坏的地下组织“世界蛇”的创始人与至高无上的尊主，亦是所有卡斯兰娜家族成员的共同先祖。",
 "achievements": [
 "在终焉之战后，抱着人类最后的希望进入休眠仓，跨越五万年将文明的火种延续至现文明。",
 "创立了以“战胜崩坏”为唯一目标的组织“世界蛇”。",
 "策划并准备发动“圣痕计划”，试图以全人类的未来为赌注，彻底终结崩坏。"
 ],
 "interests": [
 "思念梅博士",
 "构想并完善战胜崩坏的计划",
 "观察现文明人类的发展与挣扎"
 ],
