 "现文明": {
 "宣告": "「我们别无选择。」",
 "命令": "「踏上前来。」",
 "阐述理念": "「牺牲……就是牺牲，是所有与之相关的人都应永远背负的东西……也仅此而已。」",
 "对敌": "「施展出你们的一切，再度战胜我吧。若非如此……等待你们的，仍将是‘坠落’。」"
 }
 },
