    "梅比乌斯": {
      "nature": "同事、理念相悖者",
      "description": "同为逐火十三英桀的科学家。苏是为数不多能理解梅比乌斯疯狂思想的人，但他并不同意其为达目的不择手段、无视伦理的做法。两人关系微妙，经常发生争执。苏曾阻止过失控的梅比乌斯，并且因为助手克莱茵的死而与梅比乌斯产生隔阂。"
    },
    "阿波尼亚": {
      "nature": "战友、戒律的制定者",
      "description": "同为精神型融合战士的英桀。苏曾与阿波尼亚组队执行任务，并亲身感受过她那如同“神迹”般的精神威压。阿波尼亚曾制服过因仇恨而濒临失控的苏，让他从杀意中平复下来。"
    },
    "幽兰黛尔（比安卡·“琪亚娜”·卡斯兰娜）": {
      "nature": "传承者",
      "description": "在现文明，幽兰黛尔进入第二神之键，与留存在其中的苏相遇。苏对她进行了考验，最终认可了她的意志与力量，将“恒沙计划”的观测结果与“须弥芥子”的力量传承给了她，完成了自己最后的使命。"
    }
  }
}

