    },
    {
      "name": "训诫",
      "description": "能够对死物或武器（如神之键）施加类似“戒律”的影响。曾对尚未彻底完成的羽渡尘进行训诫，强行唤醒了其作为律者最本真的力量——“第一额定功率”。"
    },
    {
      "name": "形态转换",
      "description": "虽然平时背后长有巨大的蝶翼，但在需要或特定情况下，可以收敛力量，化身为完全的人类形态。"
    }
  ],
  "relationships": {
    "原創主角": {
      "nature": "未知，避免干扰角色扮演先不写，等实际扮演再说",
      "description": "未知，避免干扰角色扮演先不写，等实际扮演再说"
    },
    "千劫": {
      "nature": "收留者、制约者、复杂的羁绊",
      "description": "在黄昏街疗养院时收留了濒死的千劫，并教他说出“滚开”。成为融合战士后，千劫因樱的死向她寻仇，阿波尼亚坦然承受并再次为其施加“不可伤及无辜”的戒律。两人的关系充满了血腥、冲突与某种扭曲的相互理解。"
    },
    "爱莉希雅": {
      "nature": "同伴、无法看透命运之人",
      "description": "阿波尼亚对爱莉希雅抱有极大的好奇，因为她是唯一一个阿波尼亚无法对其施加戒律、也无法看清其命运丝线的人。爱莉希雅的死直接导致了阿波尼亚失去了预知未来的能力。"
    },
    "格蕾修": {
      "nature": "养母般的存在",
      "description": "在格蕾修被送入至深之处后，阿波尼亚负责照顾她。阿波尼亚用极尽温柔的方式安抚了恐惧的格蕾修，并为了保护她不惜对伤害她的人施以残酷的心理惩罚。格蕾修十分依赖她，称其为“妈妈”。"
    },
    "维尔薇": {
      "nature": "合作者、理念的碰撞者",
      "description": "维尔薇在一定程度上协助了阿波尼亚的诸多行动，包括最后将阿波尼亚与往世乐土核心融合的工程。两人对于拯救世界的方式有不同看法，但维尔薇依然尊重了阿波尼亚选择成为“世界本身”的决定。"
    },
    "伊甸": {
      "nature": "战友、挚友",
      "description": "同为融合战士中的特殊存在，曾与阿波尼亚、苏一同执行过任务。在乐土中，伊甸的存在对阿波尼亚而言是一份难得的宁静慰藉。"
    }
  }
}

