      "nature": "认可的对手",
      "description": "逐火英桀中最强的战士，是少数能稳赢千劫的人之一。两人曾有过多次私斗，千劫认可凯文的强大，将他视为值得全力一战的对手。"
    },
    "苏": {
      "nature": "厌烦的说教者",
      "description": "千劫非常讨厌苏的说教。在某次任务中，苏曾链接千劫的精神并操纵其身体战斗，意外发现了千劫意识深处的秘密，并解开了他的戒律。"
    },
    "华": {
      "nature": "战友",
      "description": "同为逐火之蛾的战士。千劫曾袭击过华以测试自己成为融合战士的可能性，也曾在战场上救下力竭的华。两人之间是纯粹的战友关系。"
    },
    "伊默尔": {
      "nature": "有趣的副官、专属的刺杀者",
      "description": "一个屡次越狱只为刺杀千劫的杀手。千劫非但没有杀死他，反而觉得他很有趣，并破格提拔他成为自己的副官。在千劫看来，伊默尔是唯一有资格了结自己的人，他珍视这份来自对手的执着，直到伊默尔的死亡。"
    }
  }
}

