    },
    "希娜狄雅": {
      "nature": "生死与共的战友",
      "description": "作为小队长，赫丽娅对她充满了责任感。在火星的未知探索中，赫丽娅致力于保护这位在量子之海危机中相遇的同伴。"
    },
    "寻梦者": {
      "nature": "生死与共的战友",
      "description": "火星探索小队的重要成员，赫丽娅作为队长，肩负着保护和引导寻梦者的责任，共同面对洛星系统的危机。"
