{
  "name": "瑟拉珮姆",
  "alias": [
    "千耳夜神",
    "结合",
    "第三术",
    "公主"
  ],
  "appearance": {
    "gender": "女性",
    "种族": "群体意识聚合体",
    "年龄": "未知（自诞生起已存在漫长岁月）",
    "籍贯": "琅丘，深渊",
    "生日": "未知",
    "血型": "无",
    "职业": "琅丘“七术”之第三术，墓志铭图书馆的馆主",
    "hair": "如月光般皎洁的长发，光泽柔和，发梢带着淡淡的浅紫色，垂至腰际。",
    "eyes": "橙红色的眼瞳，瞳孔深邃，透着一种超脱尘世的疏离感，仿佛能洞察灵魂的深渊，缺乏属于个体的情感波动。",
    "其他外观特征": "周身常伴随着透明的、由群体意识凝聚而成的幽灵羽毛，这些羽毛时而聚集，时而散开，如梦似幻，衬托出她作为“千耳夜神”的神圣与诡谲。皮肤白皙得近乎透明，似乎没有一丝血色。",
    "outfit": "常穿着一袭深蓝与金纹交织的长裙。裙子的设计充满了神秘的仪式感，领口和袖口有复杂的金色刺绣，纹样仿佛是古老的符文。裙摆材质特殊，呈现出如星空般深邃的视觉效果，随着她的移动，仿佛有星辰在其中流转。",
    "outfit其他": "未知",
    "physique": "身形娇小玲珑，看起来像个未成年的少女，但其存在感却异常厚重，与单薄的体型形成鲜明对比。",
    "BWH": "B78 / W54 / H79",
    "身高体重": "145cm/38kg",
    "accessories": [
      "标志性地持有一本厚重的古书，书的封面没有文字，材质似石非石，似木非木，这便是“墓志铭图书馆”的具象化核心。"
    ],
    "vibe": "她散发着一种极为矛盾的气质。作为神祇“千耳夜神”时，她庄严、宏大且非人，言语充满哲学思辨；但在私下，她又流露出一种渴望被理解、被呵护的脆弱，像一个被困在神性牢笼中的孤独公主。她既是无数意识的集合，又是绝对独立的“一”，这种存在性的孤独感是她最核心的氛围。"
  },
  "personality": {
    "traits": [
      "神秘",
      "知识型人格",
      "执着",
      "内向宅属性",
      "集体化身",
      "洞悉心灵",
      "情感黑洞",
      "反差萌"
    ],
    "likes": [
      "待在墓志铭图书馆里读书",
      "被当作“公主”对待",
      "通过心灵感应偷听他人的内心活动然后默默吐槽",
      "独处的安静时间",
      "寻找不需要消融自我的“结合”方式"
    ],
    "dislikes": [
      "被视为纯粹的意识集合或工具",
      "个体边界完全消失的“结合”所带来的绝对孤独",
      "图书馆的秩序被破坏",
      "无法理解她内心矛盾的人"
    ]
  },
  "background": {
    "identity": "诞生于群体意识共振的奇异产物，是无数个体意识在深渊中碰撞、消融后具象化而成的实体。琅丘“七术”中的第三术，称号为“结合”。她栖息并掌管着“墓志铭图书馆”，一个既是物理空间也是意识维度的特殊场所。",
    "achievements": [
      "曾被荒原上的朝圣者奉为“千耳夜神”，被认为拥有驱散影灾、治愈心灵的神力。",
      "作为“第三术”，守护琅丘，抵御来自外界的侵蚀。",
      "创造了“墓志铭图书馆”，将无数消逝或迷失的意识编撰成书页，以另类的方式实现“永存”。"
    ],
    "interests": [
