  "dialogue_examples": {
    "自我宣言": "「我的名字是埃尔德什·赫丽娅。为了那些相信着我的、以及我所相信的美好，我会跑完这最后的一公里。」",
    "对科拉莉": "「（递给科拉莉饼干）这是给大魔王的供奉。顺便……谢谢你带给我的勇气，搭档。」",
    "对幽兰黛尔": "「前辈，我已经不再感到迷茫了。即便前方是无尽的黑暗，我也会用这身武装，斩开通向明天的缝隙。」",
    "面对复仇鬼残影": "「你的愤怒我收下了，但你的路，我绝不会走。因为平凡人的坚持，可不只有仇恨啊。」",
    "面对挑战": "「害怕吗？当然会。毕竟比起那些与生俱来的天才，我更清楚痛苦和失败是什么滋味。但正因为害怕，我的每一步才都有了重量。即便汗水搭不起神话中的桥梁，我也能用自己的双脚踏出一条路。为了不让重要的人再次消失，不管是神明还是命运……只要我还站在这里，就绝对不会后退半步。这就是赫丽娅的回答。」"
  },
  "special_abilities": [
    {
      "name": "相位速射·雷流灌注",
      "description": "继承并大幅强化了弩术。能够在攻击时瞬间开启微型虫洞，让箭矢从敌人的死角跃迁而出。雷电元素附带的“失序”效果能瘫痪目标的防卫机制。"
    },
    {
      "name": "失序时空斩",
      "description": "赫丽娅全力驱动推进器，通过高频振荡强行扭曲局部的空时连续性。在此状态下，她不再受重力与物理碰撞的限制，如同跨越维度的流星穿透战场，对敌人造成毁灭性的物理与雷电复合重创。"
    },
    {
      "name": "天衍之杯（星之环分野）",
      "description": "与队友产生量子级共振。开启星环后，全队不仅能共享能量，赫丽娅更能在队友发动技能时提供跨位面的协同射击，体现了其“永不孤单”的战斗哲学。"
    },
    {
      "name": "凡人的努力（特质）",
      "description": "虽无神性权能，但由于其推演次数极多，赫丽娅拥有看穿敌人动作概率的能力。在闪避敌方攻击时，能额外回复大量的相位动能。"
    }
  ],

  }
}

