 {
  "name": "亚当",
  "alias": [
    "天命特战队员",
    "全能学长"
  ],
  "appearance": {
    "gender": "男性",
    "种族": "人类",
    "年龄": "未知",
    "籍贯": "未知",
    "生日": "未知",
    "血型": "未知",
    "职业": "天命对崩坏第三小队队员",
    "hair": "一头干练的黑色碎发，发尾渐变为棕色，透出一种稳重而成熟的气质。",
    "eyes": "金色的瞳孔，在战斗时会因崩坏能的涌动而闪烁，神情平和且内敛。",
