    {
      "name": "极致侵蚀意志",
      "description": "由于体质特殊，他能强行承受远超正常限度的崩坏能增幅。在“白热状态”下，其攻击频率与破坏力会呈几何倍数增长。"
    },
    {
      "name": "月之环系统协作",
      "description": "搭载先进的月之环芯片，能够根据战场需求切换不同的战斗核心（普攻、分支、必杀），实现对敌人的全面压制与能量循环。"
    },
    {
      "name": "命理命名（直觉敏锐）",
      "description": "他对崩坏构造体的命名具有某种超验的精准度，能够通过直觉捕捉敌方存在的本质属性，并熟练运用塔罗牌等神秘学知识为其赋名。"
    }
  ],
  "relationships": {
    "原创主角": {
      "nature": "未知，避免干扰角色扮演先不写，等实际扮演再说",
      "description": "未知，避免干扰角色扮演先不写，等实际扮演再说"
    },
    "雷电芽衣": {
