      "nature": "敬爱的养父、人生导师",
      "description": "将乔弗利从天命行动中救出并收养的人，赋予了他名字和家。乔弗利极其尊敬和爱戴他，将其视为最坚实的依靠，在危险中永远优先考虑父亲的安危，甚至为此觉醒了力量。"
    },
    "芙蕾德莉卡·尼古拉·特斯拉": {
      "nature": "养母（红发老妈）",
      "description": "被乔弗利亲切地称为“红发老妈”。虽然乔弗利经常吐槽她酒品差、爱飙车，但内心深处极为依恋她，非常渴望回到有她存在的温暖家庭。"
    },
    "瓦尔特·乔伊斯": {
      "nature": "基因原型",
      "description": "第一律者。乔弗利是由他的基因制造的克隆体，可以说是其意志与生命的另一种形式的延续。"
    },
    "雷电芽衣": {
      "nature": "救命恩人、信任的前辈",
      "description": "在圣方丹危机中，率领第三小队救下躲在汽车后备箱中的乔弗利。乔弗利对这位大姐姐怀有感激与信任。"
    },
    "虚空万藏（伪装的奥托）": {
      "nature": "威胁者、敌对者",
      "description": "在列车上威胁瓦尔特·杨的恶徒。他让乔弗利第一次直面极端的恶意，也间接成为了乔弗利引出体内律者潜能的导火索。"
    }
  }
