 {
  "name": "比安卡·阿塔吉娜", "Bianca Ataegina", "幽兰黛尔"
  "alias": [
    "幽兰黛尔",
    "天命最强女武神"
  ],
  "appearance": {
    "gender": "女性",
    "种族":"人类",
