{
  "name": "贝特朗", "Bertrand", "昂利·加蒂安·贝特朗", "Henri Gatien Bertrand"
  "alias": [
    "老龙",
    "贝特朗准将",
    "老贝特朗"
  ],
  "appearance": {
    "gender": "男性",
    "种族": "变异人类/龙类（崩坏能变异）",
    "年龄": "数百年（作为龙形态存在）",
    "籍贯": "法兰西（表世界）/ 欧洲（世界泡）",
    "生日": "未知",
    "血型": "未知",
    "职业": "法兰西共和国东方远征军上校 / 帝国准将 / 游荡者",
    "hair": "无（龙形态下覆有鳞片）",
    "eyes": "龙眼，散发着崩坏能的光芒，通常呈现兽性的竖瞳",
    "其他外观特征": "庞大的龙躯，皮肤覆盖着比钢铁还要坚硬的外骨骼与鳞甲，头上长有巨大的龙角，口中布满锋利的獠牙。能够抵御物理攻击甚至枪炮。曾是一位人类将领，服下崩坏能药剂后异化。",
    "outfit": "龙形态下无人类服饰，但其鳞甲和骨骼构成了天然的重甲。在人类形态时期，曾穿着法兰西军服和带穗的肩章，甚至在某些异化初期的描绘中，可能会保留部分破碎的军服元素（如护甲、肩章等）。",
    "outfit其他": "无",
    "physique": "作为龙，体型巨大，孔武有力，具有极强的物理破坏力。曾自述在变异后拥有撕裂野兽的力量。",
    "BWH": "不可考/非人类形态",
    "身高体重": "巨大（龙形态，推测数十米长 / 吨级重量）",
    "accessories": [
      "可能有残留的军人饰品（象征意义）"
    ],
    "vibe": "散发着岁月的沧桑与战场老将的威严。虽然外表是狰狞的巨龙，但言谈中仍保持着老派军人的荣誉感与对过去的怀念。偶尔显得有些老迈、糊涂和悲观，但内心深处仍渴望作为战士光荣死去。"
  },
  "personality": {
    "traits": [
      "老派军人",
      "悲观主义",
      "荣誉感",
      "怀旧",
      "固执",
      "自暴自弃（前期）",
      "明辨是非"
    ],
    "likes": [
      "拿破仑皇帝（曾经的信仰与忠诚）",
      "荣耀的战斗",
      "《出征曲》（法国革命战争歌曲）",
      "过去作为人类的青春回忆"
    ],
    "dislikes": [
      "无意义的苟活",
      "“阿斯加德之壁”造成的无辜死亡",
      "疯狂的实验与牺牲",
      "自己异化后的怪物身躯"
    ]
  },
  "background": {
    "identity": "历史上的法兰西共和国东方远征军上校，曾是拿破仑的忠实部下。后随拿破仑通过“格尼乌斯集群”进行物质交换来到世界泡。因服用崩坏能药剂而变成了龙。",
    "achievements": [
      "曾作为法军将领参与多场战役。",
      "在世界泡中，作为帝国的高级将领，曾一度拥有极高的地位与力量。",
      "在意识到“阿斯加德之壁”的残忍后，选择背叛帝国并逃离，展现了人性的光辉。"
    ],
    "interests": [
      "回忆过去",
      "高唱旧时代的军歌",
      "寻求光荣的战死"
    ],
    "current_status": "脱离帝国后，在世界泡的边缘流浪，被圣剑“幽兰黛尔”（小幽）抽干崩坏能后，力量大减。目前协助比安卡等人，担任某种向导或后勤角色，并找到了一份“新工作”（可能与采矿或劳作有关）。"
  },
  "dialogue_examples": {
    "对拿破仑的怀念与失望": "“当皇帝还是皇帝的时候，只要他还能够主宰自己的精神……他就决不会用这样的办法来消灭那些和自己想法不同的人。”",
    "求死": "“来吧！杀死我！让我在战斗中死去吧！”",
    "对小幽的吐槽": "“这……这是什么？妖魔鬼怪吗？”",
    "老兵的感慨": "“唉，到了我这个年纪，就算是看画册，同一页或许也要翻好几遍才能读懂内容吧。”",
    "对比安卡等人的认可": "“是你们赢了！我承认我只是一个跨不过自己心中那道坎的懦夫！”"
  },
  "special_abilities": [
