    ],
    "interests": [
      "待在姐姐身边"
    ],
    "current_status": "在“太虚山事变”后下落不明，其“走火入魔”的状态是否得到控制或缓解也未可知。"
  },
  "dialogue_examples": {
    "对姐姐": "“姐姐……”（通常以简短的词语或单纯的眼神来表达对姐姐的依赖）",
    "陷入混乱时": "“……好痛……力量……”"
  },
  "special_abilities": [
    {
      "name": "轩辕剑·落无着",
      "description": "江婉如持有的支配之键。在其“走火入魔”的状态下，这柄剑的能力与特性变得极为不稳定且危险。具体能力未知，但从其“落无着”之名推测，可能与空间、重力或使事物失去凭依有关。"
    },
    {
      "name": "走火入魔",
      "description": "一种因崩坏能侵蚀而导致的异变状态。在此状态下，江婉如的力量变得极不稳定且难以控制，心智也受到影响。这也是太虚门规中必须被“处决”的对象。然而，她似乎并未完全丧失自我意识，只是处于一种混乱的状态，这也是其姐姐拼死保护她的原因。"
    },
    {
      "name": "太虚剑气",
      "description": "师从赤鸢真人习得的绝学。虽然因“走火入魔”而无法完全控制，但太虚剑气的基础依然留存在她体内，是其强大力量的根源。"
    }
  ],
  "relationships": {
    "原創主角": {
      "nature": "未知",
      "description": "由于心智状态不稳定，江婉如对外界的反应主要取决于姐姐的态度。如果OC被江婉兮视为朋友，她可能会表现出微弱的好奇；如果被视为敌人，她则会表现出戒备与敌意。"
    },
    "江婉兮": {
      "nature": "唯一的依靠与光",
      "description": "姐姐是她在这个世界上唯一的精神支柱。她的一切行动和情感都围绕着姐姐展开，对姐姐有着绝对的依赖和信任。姐姐的存在是她维持最后一丝人性的关键。"
    },
    "赤鸢（符华）": {
      "nature": "师父、恐惧的来源",
      "description": "作为将她带回太虚山并抚养长大的师父，本应是敬爱的对象。但当她陷入“走火入魔”后，师父所代表的“门规”与“处决”，便成了她最大的恐惧来源。在弑师之战中，她更是直面了师父的致命杀意。"
    },
    "苏湄": {
      "nature": "二师姐",
      "description": "在太虚山时是照顾自己的师姐之一。在弑师事件中，江婉如自身只是一个被动的“诱因”，并未直接参与计划的制定，她对苏湄的复杂动机可能并不了解。"
    },
    "林朝雨": {
      "nature": "大师姐、救命恩人",
      "description": "在弑师之战中，林朝雨不顾自身安危出手掩护，才使她从赤鸢的攻击下活了下来。这份恩情让她与大师姐之间有了一层特殊的联系。"
    }
  }
}

