 "description": "马非马自幼便倾心于苏湄，即使后来与林朝雨成婚，这份感情也未曾改变。他心甘情愿被苏湄利用，为她做任何事。苏湄是唯一能深刻理解马非马内心孤独的人，但她对马非马的情感却并非纯粹的爱恋，充满了利用与算计。"
 },
 "符华（赤鸢）": {
 "nature": "师父",
 "description": "传授马非马武艺的恩师。马非马参与了二十年前的弑师计划，但对师父的感情远比林朝雨等人淡薄。他了解师父的强大，在得知其复活后，选择积极应对，四处奔走传递消息。"
 },
 "程凌霜": {
 "nature": "五师姐",
 "description": "七剑中天赋最高之人。马非马自认在外功上胜过她，但在剑心与剑神境界上则望尘莫及。他从小便不擅长与这位情感淡漠的师姐交流，但内心深处仍将其视为值得尊敬的同门。"
 },
 "李素裳": {
 "nature": "师侄",
 "description": "七师妹秦素衣之女，五师姐程凌霜的弟子。马非马初遇素裳时，因其携带轩辕剑而产生警惕，并与其交手。他欣赏素裳的武学天赋与不屈的意志，将其视为有趣的后辈。"
 },
 "奥托·阿波卡利斯": {
 "nature": "敌人、认可的对手",
 "description": "马非马对这个神秘的罗刹人怀有本能的厌憎与警惕，并从其身上感受到了足以杀死自己的威胁。为了寻求极致的战斗体验，他强迫奥托与自己对决，并将其视为平生罕见的强大对手。"
 }
 }
}

