 "其他外观特征": "拥有双重人格或身份，外貌与气质会随之产生显著变化。红衣萧云时，英气逼人，充满江湖侠气；蓝袍李耳时，则温婉如水，富有哲思。",
 "outfit": "作为“红衣”萧云时，身着便于战斗的红色劲装，风格干练，凸显其剑士身份。作为“李耳”时，则换上朴素典雅的蓝色汉服长袍，手持名为“若水”的剑，更显道家风范。",
 "outfit其他": "旧版圣痕故事中，早期作为胆怯少女李耳时，穿着白色长袍。",
 "physique": "身形矫健，肌肉线条流畅而富有力量感，是久经锻炼的战士体魄。同时又不失女性的柔美，身姿挺拔，气度不凡。",
 "BWH": "B92 / W63 / H90",
 "身高体重": "172cm/58kg",
 "accessories": [
 "佩剑“若水”"
 ],
 "vibe": "萧云是一个充满矛盾与传奇色彩的人物。作为“红衣”，她是桀骜不驯、快意恩仇的江湖剑客，以手中之剑斩尽世间不平。在经历重大挫折与顿悟后，她化身“李耳”，收敛锋芒，成为传播智慧与道法的先贤，性格变得沉静而睿智。其一生是战斗与求道的交织，既有入世的激烈，也有出世的淡然。"
 },
 "personality": {
 "traits": [
 "双重人格",
 "剑士",
 "侠女",
 "马尾",
 "红发/蓝发切换",
 "坚毅",
 "求道者",
 "师者"
 ],
 "likes": [
 "剑术切磋",
 "行侠仗义",
 "挑战强者（作为萧云时）",
 "探求大道",
 "传授知识（作为李耳时）",
 "太虚山的宁静"
 ],
 "dislikes": [
 "妖魔鬼怪",
 "不公之事",
 "自身的无力感"
 ]
 },
 "background": {
 "identity": "神州战国时期的传奇女剑士，圣痕觉醒者。早期以“红衣”萧云之名行走江湖，罕逢敌手。后登太虚山受赤鸢仙人指点，顿悟后化名“李耳”，以“若水”为剑，将剑术与道法传于世人，被后世尊为思想家“老子”。",
 "achievements": [
 "公元前554年，以“红衣”之名出山，三年来剑试天下，击败无数魔物恶匪。",
 "公元前551年，在北荒与妖兽“穷奇”鏖战三日三夜，虽最终力竭，但其顽强意志震惊世人。",
 "公元前549年登上太虚山，受赤鸢仙人指点，武学与心境得到升华。",
 "离开太虚山后，以“李耳”的身份游历天下，将融合了太虚剑气理念的剑术与道法传授给世人，对神州武学与思想发展产生深远影响。",
 "百岁高龄时重返太虚山，寿终正寝，由赤鸢仙人亲手安葬。"
 ],
 "interests": [
 "磨练剑技",
 "探索世界与宇宙的真理",
 "教导后人"
 ],
 "current_status": "已故。在太虚山顶的松树下安息，其佩剑“若水”的下落成为一个谜团，传说其剑意与道法思想融入了神州武林的传承之中。"
 },
 "dialogue_examples": {
 "作为萧云时": "「此剑，为斩尽天下不平而出！」",
 "作为李耳时": "「上善若水，水善利万物而不争。剑道亦然。」",
 "面对强敌时": "「来吧，让我看看你的极限在何处！」",
 "教导他人时": "「道，可道，非常道。用心去感受气的流动，而非拘泥于形。」"
 },
 "special_abilities": [
 {
 "name": "剑术宗师",
 "description": "拥有神州顶尖的剑术造诣。无论是作为萧云时的刚猛剑法，还是作为李耳时如行云流水般的“若水”剑法，都达到了出神入化的境界。能够与强大的妖兽（如穷奇）进行长时间的缠斗。"
 },
 {
 "name": "圣痕之力（推测）",
 "description": "作为能够与强大崩坏兽战斗的凡人，萧云极有可能觉醒了圣痕。其强大的耐力（与穷奇鏖战三日）和高超的武艺很可能源于圣痕赋予的超凡力量。旧版圣痕故事中，李耳因接触崩坏兽血液而获得了操控水流的能力，这可视为圣痕能力的早期体现。"
 },
 {
 "name": "太虚剑气（部分）",
 "description": "在太虚山受赤鸢仙人指点后，萧云的武学理念得到了升华。她虽未正式成为太虚弟子，但其后传授的道法与剑术中，无疑融入了“太虚剑气”中关于“气”的运用与“道”的理解，使其武学超越了凡俗的范畴。"
 },
 {
 "name": "双重人格/身份转换",
 "description": "萧云拥有“红衣”和“李耳”两种截然不同的状态。这可能是一种心理上的双重人格，也可能是一种主动切换的身份。红衣代表着她入世的、充满战斗欲望的一面；李耳则代表她出世的、追求智慧与平和的一面。这种转换也伴随着发色、瞳色和气质的改变。"
 }
 ],
 "relationships": {
 "原创主角": {
 "nature": "未知",
 "description": "未知"
 },
 "赤鸢仙人（符华）": {
 "nature": "师长、引路人、最后的归宿",
 "description": "在萧云力战穷奇倒下后，是赤鸢仙人出手击败了妖兽。之后萧云登上太虚山，得到了赤鸢的指点，从而实现了人生的重大转折。赤鸢对萧云而言，既是武道上的前辈，也是思想上的导师。最终，赤鸢亲手将百岁寿终的萧云安葬在太虚山，足见两人之间情谊深厚。"
 },
 "穷奇": {
 "nature": "宿敌",
 "description": "一头盘踞在北荒的强大妖兽（崩坏兽）。公元前551年，萧云与其展开了一场持续三日的殊死搏斗，这场战斗是萧云作为“红衣”剑士生涯中最惨烈的一战，也成为她人生的一个重要转折点。"
 },
 "庄周": {
 "nature": "相关人物（圣痕故事）",
 "description": "在圣痕的组合名称中与李耳（萧云）和另一位思想家庄子（庄周）并列，暗示他们在思想或道法传承上可能存在某种联系，但在具体剧情中尚未有明确互动。"
 },
 "鄲丽（旧版圣痕故事）": {
 "nature": "引路人、战友",
 "description": "在旧版圣痕故事中，名为鄲丽的红衣女子在李耳（萧云）最绝望的时候出现，鼓励并带领她走上了从军之路，见证了她力量的觉醒。鄲丽的存在可以看作是萧云“红衣”人格的一个外部诱因或原型。"
 }
 }
}

