    "冲锋队队长",
    "格斗教官"
  ],
  "appearance": {
    "gender": "女性",
    "种族":"人类",
    "年龄":"25岁 (生前状态)",
    "籍贯":"未知",
    "生日":"未知",
    "血型":"未知",
    "职业":"天命总部直属格斗教官、女武神冲锋队队长、兼职女仆",
    "hair": "一头由棕色渐变为红色的长发，通常扎成低马尾，干练又不失柔和。",
    "eyes": "温暖而坚定的红瞳，仿佛蕴含着不灭的火种与温柔的力量。",
    "其他外观特征": "神情总是带着一种包容万物、历经世事却依旧纯净的温柔微笑。",
    "outfit": "主要穿着一套以黑白为主色的制服，内搭白色衬衣与黑色马甲，外罩一件黑色披风，边缘饰有红色线条。下身穿着黑色短裤与白色过膝长靴，腿部有黑色的绑带装饰，整体兼具战斗的实用性与教官的威严。",
    "outfit其他": "在咖啡店打工进行社会实践时，会穿着经典的女仆装。",
    "physique": "身姿高挑挺拔，常年挥舞大剑锻炼出的肌肉匀称而充满爆发力，散发着成熟可靠的战士气质。",
    "BWH": "B92 / W60 / H88",
    "身高体重": "170cm / 58kg",
    "accessories": ["背后常背负着一把与其体型形成鲜明对比的超重剑"],
    "vibe": "给人一种如冬日暖阳般温和、纯净、优雅却又无比强大的感觉。她既是能在战场上挥舞巨剑斩碎崩坏的英勇战士，也是能在花店前温柔解救平民、在孤儿院教导孩子种花、在咖啡店聆听他人心声的知心长姐。"
  },
  "personality": {
    "traits": [
      "温柔包容",
      "传道授业解惑",
      "尽责的前辈与上司",
      "坚定的信念",
      "平易近人",
      "勇敢果决",
      "富有同理心"
    ],
    "likes": [
      "教导后辈",
      "园艺 (特别是种植百合)",
      "在咖啡店当女仆聆听真实心声",
      "为世界上所有的美好而战",
      "保护弱小"
    ],
