    },
    "丽塔·洛丝薇瑟": {
      "nature": "救命恩人、引路人、效仿对象",
      "description": "拉格纳在曼彻斯特救下了年少的丽塔，其优雅强大与当女仆体察人心的理念深深折服了丽塔。丽塔不仅被引荐加入天命，更是效仿拉格纳成为了女仆，以此作为自己守护他人的方式。"
    },
    "奥托·阿波卡利斯": {
      "nature": "上司、精神启蒙者",
      "description": "天命主教。是奥托的一席话解开了拉格纳初为女武神时的迷茫，让她明白了守护美好的意义，从而确立了其一生的信念。"
    },
