    "interests": [
      "编排新的舞蹈动作",
      "保养她的12枚利刃"
    ],
    "current_status": "已阵亡（在第二次崩坏中，为了保护车辆被贝纳勒斯杀害）。"
  },
  "dialogue_examples": {
