 {
  "name": "莎布·尼古拉斯","Shub-Niggurath", "シュブ・ニグラス",
  "alias": [
    "混沌子嗣",
    "天命南美支部最优秀女武神"
  ],
  "appearance": {
    "gender": "女性",
    "种族":"人类（被休格丝一族寄生）",
    "年龄":"未知",
