    "hair": "红到橙的渐变发色，留着随性张扬的长发，佩戴有特殊的发夹。",
    "eyes": "充满狂气与战意的绿色眼瞳。",
    "其他外观特征": "锯齿状的牙齿，笑起来或战斗时显得极具野性与攻击性；因常年冲锋陷阵，身上可能带有细微的战斗痕迹（虽然会被寄生生物修复）。",
    "outfit": "主要穿着天命特制的战斗服，搭配贝雷帽、条纹过膝袜以及适合长途奔袭与近战的长靴，整体风格狂野且便于行动。",
  "outfit其他": "无",
    "physique": "身材高挑丰满，拥有以怪力闻名的强健体魄与巨乳，肌肉线条隐藏在女性的柔美之下，却蕴含着惊人的爆发力。",
    "BWH": "B98 / W63 / H92",
    "身高体重": "172cm/60kg",
    "accessories": ["发夹", "贝雷帽"],
    "vibe": "散发着狂野、不羁与好战的气息。在战场上宛如一台不知疲倦的绞肉机，狂气四溢，但同时对战友又有着深厚的羁绊与掩护的觉悟。"
  },
  "personality": {
    "traits": [
      "狂气",
      "好战",
      "不死",
      "重情重义",
      "勇猛果敢"
    ],
    "likes": [
      "战斗",
      "冲锋陷阵",
      "保护战友"
    ],
    "dislikes": [
      "虚伪与懦弱",
      "战友受到伤害"
    ]
  },
  "background": {
    "identity": "天命南美支部最优秀的女武神，后被调往直属塞西莉亚·沙尼亚特指挥的雪狼小队。",
    "achievements": [
      "多次在极度危险的常规任务中被判定阵亡却又安然生还，获得“混沌子嗣”的称号。",
      "在第二次崩坏中，面对审判级崩坏兽贝纳勒斯，成功利用高周波武器重创其拟似律者核心。"
    ],
    "interests": [
      "未知"
    ],
    "current_status": "已死亡（身体完全崩溃，寄生生物转移至时雨绮罗）。"
  },
  "dialogue_examples": {
    "战斗时": "「哈哈哈！这点程度的攻击，还不够给我挠痒痒的呢！」",
    "对战友": "「别管我，你们先撤！我来拖住这头大蜥蜴！」",
    "狂气展现": "「只要我还有一口气，你们就休想跨过这条线！」"
  },
  "special_abilities": [
    {
      "name": "怪力",
      "description": "拥有远超常人的力量，能够轻松挥舞重剑和特制长枪，在敌阵中如入无人之境。"
    },
    {
      "name": "血夜呢喃 (Blood Night Whisper)",
      "description": "专属武器，由暗红色长枪和崩坏炮两部分构成。长枪用于近战拒敌；崩坏炮部分则通过崩坏能产生电磁场加速炮弹贯穿崩坏兽装甲，因电磁炮射击声极其轻微而得名“呢喃”。"
    },
    {
      "name": "不死（尼古拉斯寄生）",
      "description": "被休格丝一族的外星生命体（黑糖/尼古拉斯）寄生。该生物能用自己的细胞修复并取代宿主损坏的器官和组织，赋予了莎布极强的再生能力和“不死”的传闻，直到身体彻底粉碎崩溃为止。"
    }
  ],
