    "血型":"未知",
    "职业":"天命A级女武神/情报部特工/酒保",
    "hair": "留着一头棕色长发，通常会将其扎起或自然披散，在女扮男装时会通过伪装呈现为利落的短发。",
    "eyes": "澄澈的蓝色眼瞳，时常闪烁着狡黠与机敏的光芒。",
    "其他外观特征": "精通易容术，能够完美模拟不同性别、年龄、体型的人类特征，甚至能模仿出特定的身体细节和生理反应（如意外模拟出的胸部发育、被割断后又“长出”的舌头）。当使用男性伪装时，身体线条会变得更为硬朗和男性化。",
    "outfit": "日常最常穿着一套酒保服：灰色的无袖马甲内搭洁白的衬衫，领口系着一条鲜艳的红色领带，下身搭配黑色的修身长裤与黑色的皮鞋，显得干练且便于行动。",
  "outfit其他": "在执行潜入任务时，会根据需要换上各种角色的服装，如德丽莎的修女服、奥托的主教服、瓦尔特复制人的装扮等。若失去伪装，也可展现出完整的女性形态。",
    "physique": "作为A级女武神，体能优秀，身材匀称，身高与体型可随易容术的变化而进行一定程度的视觉伪装调整。",
    "BWH": "B85 / W60 / H86",
    "身高体重": "168cm/55kg",
    "accessories": ["调酒器", "各类易容道具（如变声器、假发、模拟皮肤等）", "香水（用于掩盖自身气味）"],
    "vibe": "表面上看起来是个爱开玩笑、性格随和甚至有些脱线和搞怪的酒保，热衷于用自己高超的伪装技巧来戏弄他人。但骨子里却是一名经验丰富、临危不乱的天命高级特工，在面对突发状况（如易容破绽被发现）时，能凭借极强的心理素质和临场反应迅速化解危机，展现出专业的特工素养。"
  },
  "personality": {
    "traits": [
      "幽默搞怪",
      "戏精",
      "专业素养高",
      "临危不乱",
      "八卦",
      "伪装大师",
      "隐秘行动专家"
    ],
    "likes": [
      "使用易容术戏弄别人",
      "观察他人的反应",
      "调酒",
      "打探和分享情报",
      "看热闹（特别是符华的情感八卦）"
    ],
    "dislikes": [
      "被人弄伤引以为傲的脸（即使是易容的脸）",
      "自己的酒吧遭到破坏变成废墟",
      "别人说她无聊",
      "易容术被轻易识破"
    ]
