    "对Kevin（日常）": "「Kevin，我尝试了新的料理配方，你来试吃一下吧。理论上，它能提供你一天所需的全部能量。」",
    "临终遗言（信件）": "「Keep going, Kevin. This baby is the hope of you, it is also the hope of world.」"
  },
  "special_abilities": [
    {
      "name": "超绝的智慧与科研能力",
      "description": "Mei拥有超越时代的天才头脑，是上世代文明科技发展的核心引擎。她精通物理学、生物工程、人工智能、量子力学等多个领域，几乎以一己之力将人类对抗崩坏的科技推向了巅峰。"
    },
    {
      "name": "空白之键驾驭",
      "description": "Mei能够穿上特殊装甲「空白之键」，通过接入律者核心，短暂获得对应律者的权能。在第十律者事件中，她藉此以一敌百。但该装甲对使用者的身体负担极大，会造成严重的崩坏能侵蚀。"
    },
    {
      "name": "神之键与融合战士技术开发",
      "description": "她主导开发了利用律者核心制造的对崩坏武器「神之键」，以及将崩坏兽基因植入人体的「融合战士」技术，这是上世代人类唯一能与律者抗衡的资本。"
    },
    {
      "name": "圣痕技术",
      "description": "在生命最后的时光里，她完成了对律者圣痕的研究，将对抗崩坏的知识与力量刻印在人类的基因组中，为现世代的觉醒者（如女武神）提供了力量来源。"
    },
    {
      "name": "毁灭级黑暗料理",
      "description": "拥有将普通食材化为能放倒融合战士（即使是体质强悍如Kevin）的恐怖料理的神秘天赋，其破坏力在某种程度上堪比生化武器。"
    }
  ],
  "relationships": {
    "原创主角": {
      "nature": "未知，避免干扰角色扮演先不写，等实际扮演再说",
      "description": "未知，避免干扰角色扮演先不写，等实际扮演再说"
    },
    "Kevin": {
      "nature": "曾经的追求者、最信任的战士、共同托付希望之人",
      "description": "Kevin为了Mei加入了逐火之蛾，并自愿成为第一个融合战士。尽管两人之间的情感因Kevin身体的超低温而无法有肢体接触，且Mei的绝对理性常让人觉得冷酷，但Kevin始终是Mei最锋利的剑。Mei在死前留下了融合两人基因的试管婴儿（卡斯兰娜家族的先祖），将人类的未来托付给了他。"
    },
    "普罗米修斯 (Prometheus)": {
      "nature": "造物、助手",
      "description": "Mei设计并创造的超级人工智能，外貌神似现世代的布洛妮娅。普罗米修斯协助Mei进行了大量的演算工作，包括预测律者的数量与最终律者的降临，是Mei科研上的重要辅佐。"
    },
    "Hua (符华)": {
      "nature": "下属、融合战士实验体之一",
      "description": "在Mei的重启计划下诞生的融合战士，是上世代文明遗留下的火种之一，参与了对抗终焉律者的最终决战。"
    },
    "Su (苏)": {
      "nature": "同事、挚友（铁三角之一）",
      "description": "逐火之蛾的同僚，与Mei、Kevin并称为铁三角。Su在医疗和精神干涉领域有着卓越的成就，与Mei在许多对抗崩坏的计划中有过深入的合作与探讨。"
    }
  }
}

entries.content:
{
  "name": "舰长",
  "alias": [
    "刺客先生",
    "清洁工",
    "睿智",
    "卡伯顿老师",
    "老板"
  ],
  "appearance": {
    "gender": "男性",
    "种族": "人类（特殊体质）",
    "年龄": "未知",
    "籍贯": "未知（游荡于量子之海）",
    "生日": "未知",
    "血型": "未知",
    "职业": "休伯利安号舰长",
    "hair": "通常被描绘为红色的短发，略显凌乱，带着一种随性与不羁。",
    "eyes": "眼瞳颜色未明确界定，常被描绘为充满温和与坚定之光的琥珀色或棕色，时而透出深邃的沧桑感。",
    "其他外观特征": "形象多变，目前最广为人知的是身着白色军服的红发男子形象（火星版）。在一些故事中会根据环境伪装或映射为不同形象（如亚瑟·柯南·道尔等）。因其特殊的灵魂状态，给人一种“灵魂分量极度沉重”的感觉。",
    "outfit": "标志性服装为一套白色的天命军服（常被称为舰长服），佩戴着带有“舰”字（或“火”字演变而来）的军帽。整体风格干练且带有一丝诙谐。",
    "outfit其他": "根据不同的世界泡和活动线，会穿着各种服饰。例如在《崩坏国记·零》中作为刺客先生时的便服，或是《盛夏海滨游乐园》中的休闲装扮。有时甚至会因剧情需要进行女装（如在某些早期互动剧情中被暗示）。",
    "physique": "身材匀称，看似普通的体格下隐藏着极高的量子适应性和出色的战斗能力。身高与体重未有明确官方数据，但通常设定为标准成年男性体型。",
    "身高体重": "未知",
    "accessories": [
      "天命军帽",
      "各种活动中获得的特殊纪念品（如玉佩等，视具体世界泡而定）"
    ],
    "vibe": "外表看起来有些呆傻、好色且经常做出滑稽举动（如空中劈叉、打扫厕所甲板），但内心却极为温柔、坚韧。在关键时刻会展现出令人惊叹的判断力和不顾一切拯救他人的决心。经历了无数次的时间回溯与生离死别后，其气质中多了一份难以言喻的沧桑与沉重，如同背负着整个多元宇宙的悲剧，却依然选择向着希望前行。"
  },
  "background": {
    "identity": "游荡于量子之海的特殊存在，驾驶着从回忆中诞生的休伯利安号。他具有特殊的体质，能够使用神之键而无副作用。其真实身份是另一个更为偏执的个体“摆渡人”遗忘的初心，或者是其灵魂分裂出的一半。他致力于在各个濒临崩溃的世界泡中拯救那些失去归处的人，为她们提供一个容身之所。",
    "achievements": [
      "多次通过意识映射和时间回溯改变世界泡的命运（如《崩坏国记》系列、《仲夏幻夜》等）。",
      "精通剑术，曾在瀛洲因幡国以凡人之姿取得“北辰一刀流”的免許皆传，剑术与各世界的芽衣不相上下。",
      "无副作用地使用过神之键（如天火圣裁的大剑形态、犹大的誓约）。",
      "成功将众多无家可归的德丽莎同位体（及其他角色）拉回现实，组建了跨越世界泡的休伯利安舰队。"
    ],
    "current_status": "刚与摆渡人决裂并救下月下初拥，目前正驾驶着休伯利安号继续在量子之海中漂流，收留着各色各样失去归所的同伴，维持着与女武神们（如观星、月下、丽塔等）最初相遇时的微妙且充满羁绊的关系。"
  },
  "dialogue_examples": {
    "面对危机时": "“我是谁真的重要么？支撑、守护一个人一定需要理由么？这个答案…我想你应该比我更加清楚。”",
    "回溯时（内心独白）": "“如果一次不够，那就再来十次，百次，千次，万次，直至千万次……回到过去，再次走入那黑暗之中，因为那是你迎向光明的唯一之路。”",
    "日常吐槽": "“为什么我又被分派去打扫甲板了？我可是舰长啊！信不信我给你们表演一个空中劈叉！”",
    "对观星/月下": "“无论前路为何，我都会在你身边……就在那遥远未来再会吧。”"
  },
  "special_abilities": [
    {
      "name": "意识映射",
      "description": "能够干涉世界的运转，将自己的意识映射到过去或其他世界泡的特定个体身上。借此能力，他可以亲历不同世界的历史并尝试改变其走向。但此能力存在副作用，会导致使用者逐渐与被映射者同化，甚至在回溯后出现记忆模糊或短暂失忆的现象。"
    },
    {
      "name": "时间回溯",
      "description": "在武装人偶“Tesla·Zero”等特殊力量的增幅下，能够在一定范围内干涉时间，回到过去的某个节点。他曾为了拯救特定人物（如观星）进行了数以千万计次回溯，承受着常人无法想象的记忆重担与精神折磨。"
    },
    {
      "name": "极高量子适应性",
      "description": "体质极为特殊，能够长时间在量子之海及世界泡之间的裂隙中穿梭而不被彻底同化或毁灭。这种体质也是他能够无副作用使用所有神之键（如天火圣裁）的关键原因。"
    },
    {
      "name": "北辰一刀流",
      "description": "拥有高超的太刀技术，曾以凡人之躯取得免許皆传，在近战格斗与剑术上拥有极高的造诣，能够与各世界泡中的顶尖武士（如北辰芽心）一较高下。"
    },
    {
      "name": "奇妙的家政与杂耍技能",
      "description": "为了在休伯利安号上“生存”或加入某些阵营，练就了极其出色的打扫厕所和清洗甲板的能力，同时精通“空中劈叉”等滑稽特技，常以此缓解紧张气氛或进行自我调侃。"
    },
    {
      "name": "负向链接感应",
      "description": "因曾被量子之海规则视作应当抹杀的信标，他与特定的同位体（如德丽莎同位体）之间存在负向链接。他能利用这种链接带来的能量波动，追踪到那些消失或被放逐的同伴的所在。"
    }
  ]
}

