    "eyes": "血红色的眼瞳，在吸血冲动发作或战斗时会闪烁出妖异的红光，平时则带有几分懵懂与无辜。",
    "其他外观特征": "拥有类似吸血鬼的尖牙，皮肤异常苍白。耳朵比普通人类稍尖。虽然外表是娇小的少女，但由于体内的崩坏兽细胞和侵蚀之键能量，散发着危险而神秘的气息。",
    "outfit": "主要穿着一套名为「花裳月纱」的哥特风连衣裙（或初始装甲服饰）。裙摆以黑色和深红色为主色调，层层叠叠的蕾丝与荷叶边装饰，胸前佩戴着带有十字架元素的饰品。双手戴着黑色半透明的蕾丝手套，腿部穿着黑色的过膝长筒袜与红色高跟鞋。",
    "outfit其他": "无记录其他常规服装",
    "physique": "身姿娇小，体态轻盈，保留着孩童般的纯真感，但体内蕴含着远超常人的怪力与敏捷。",
    "BWH": "B70 / W54 / H73",
    "身高体重": "145cm / 38kg",
    "accessories": [
      "红玫瑰发饰",
      "十字架项圈"
    ],
    "vibe": "平时表现得如同一个不谙世事、渴望探索外界的纯真孩童，对未知事物充满好奇，带有一丝惹人怜爱的脆弱感。然而，一旦被吸血冲动控制或进入战斗状态，便会展现出狂暴、嗜血的一面，如同被诅咒的暗夜眷属。对给予她温暖的人（如舰长、卡莲）有着极深的依恋与占有欲。"
  },
  "personality": {
    "traits": [
      "吸血冲动",
      "渴望自由",
      "极度依恋",
      "纯真懵懂",
      "潜在的狂暴",
      "病娇潜质（对舰长）",
      "孤独"
    ],
    "likes": [
