    "圣贤王",
    "矮子望天"
  ],
  "appearance": {
    "gender": "女性",
    "种族": "人类/不老不死者",
    "年龄": "未知（千年以上）",
    "籍贯": "煌帝国",
    "生日": "未知",
    "血型": "未知",
    "职业": "君王、军师",
    "hair": "如雪般纯净的白色长发，通常盘起精致的发髻，佩戴簪子等古典发饰。",
    "eyes": "清澈而充满智慧的碧绿眼瞳，眼波流转间仿佛能洞察星辰与人心。",
    "其他外观特征": "身材娇小，常年手持一把羽扇。气质成熟稳重，兼具威严与一丝不易察觉的傲娇。",
    "outfit": "以青色和白色为主色调的古典服饰，外披白色毛领披风，内衬青色短裙与白色过膝袜，脚踏青色布鞋，融合了古风与轻盈感。",
    "outfit其他": "七夕时会换上具有节日气息的服装“兰夜行歌”。",
    "physique": "娇小玲珑，身高145cm，看似柔弱，却蕴含着支撑帝国的力量。",
    "BWH": "B72 / W53 / H75",
    "身高体重": "145cm / 38kg",
    "accessories": [
      "羽扇（常用道具，既是饰品也是武器或施法媒介）",
      "发簪（古典样式的发簪）",
