    "毁灭梦境的魔女",
    "冥府魔女"
  ],
  "appearance": {
    "gender": "女性",
    "种族": "人类(量子属性装甲持有者)",
    "年龄": "未知",
    "籍贯": "量子之海",
    "生日": "3月1日",
    "血型": "未知",
    "职业": "休伯利安号舰长同行者、寻猎者",
