    "outfit": "主要穿着一套以黑色和红色为主色调的紧身忍者服，上身是带有交叉绑带的无袖紧身衣，下身是黑色短裤和高低不一的长筒袜与腿甲。双臂戴有黑色手套和护臂，腰间系有红色的绳结与配饰，整体风格兼具机动性与隐蔽性。另外有一套名为「桃源一梦」的新春服装，风格更为温婉，带有毛领和精致的花纹。",
    "outfit其他": "桃源一梦：梦入桃源落樱楼，弦音袖舞几时休。莫道佳人无好酒，清茶亦可解君愁。",
    "physique": "身姿矫健，体态匀称，因为长期的忍者修行而拥有极高的爆发力与柔韧性，动作轻盈无声。",
    "BWH": "B88 / W59 / H89",
    "身高体重": "165cm / 49kg",
    "accessories": [
      "狐狸面具（常斜戴于头部或挂在腰间）",
      "苦无",
      "太刀"
    ],
    "vibe": "外在表现为一名冷酷无情、只为完成任务的称职忍者，习惯将真实的自我隐藏在阴影之中。言辞简练，对痛觉和等待有着极强的忍耐力。但在接触到温暖（如舰长/摆渡人）后，内心柔软的一面逐渐显露，对归宿有着深深的渴望与珍视。"
  },
  "background": {
    "identity": "天命暗部的忍者，实质上是用八重樱身上尚未坏死的细胞克隆出来的婴儿，寄宿着八重樱的灵魂但没有其记忆。后被奥托培养并赋予“霞”的代号，最终加入摆渡人的休伯利安号，成为其直属部下。",
    "achievements": [
      "在八重町追查并回收了具有神秘力量的忍法帖——「外道六法」。",
      "参与调查多个世界泡失踪的德丽莎事件。",
      "将扮演萝莎莉娅的德尔塔成功抓回给摆渡人复命。"
    ],
    "current_status": "作为摆渡人（舰长）的直属部下，在休伯利安号上生活，并参与在其他世界泡的各项行动。将休伯利安视为自己有生以来获得的第一处归宿。"
  },
  "dialogue_examples": {
    "对待任务": "「真正的忍者，不会留给敌人一丝破绽。」",
    "面对温暖/归宿": "「这座休伯利安，是我有生以来获得的第一处归宿。」",
    "日常互动": "「舰长，可以不要一直盯着我的耳朵嘛……」",
    "战斗宣言": "「外道六法——开！」"
  },
  "special_abilities": [
    {
      "name": "空明鬼魇",
      "description": "特殊的咒术技能。通过投掷苦无在敌人身上施加咒印，提升自身造成的伤害。在晋升后，该技能还能进一步提升全伤害、强化分支攻击并提高咒力上限。"
    },
    {
      "name": "分支-奈落",
      "description": "消耗咒力释放的连续攻击。能够对范围内的敌人造成雷电元素伤害。随着连续释放，其伤害会逐渐提高，并且对低血量敌人有额外的伤害加成。"
    },
    {
      "name": "外道六法",
      "description": "必杀技。召唤祸世狐妖以雷霆之姿短暂现世，造成大范围雷电元素伤害。随后可施展第二段「六道杀阵」，触发雷霆斩击并麻痹敌人，同时提升自身的抗打断能力并获得全伤害减免。"
    },
    {
      "name": "我流",
      "description": "融合了剑术与体术的普通攻击。连续的攻击不仅能造成物理与雷电元素混合伤害，还能快速回复咒力和能量。"
    },
    {
      "name": "雷神瞬身",
      "description": "极限闪避技能。在闪避的同时用雷电在原地凝聚一个替身吸引敌人，替身爆炸后造成高额雷电元素伤害并触发全局时空断裂。触发后角色进入隐身疾跑状态，可发动「忍杀」进行突袭。"
    },
    {
      "name": "沉沦八苦",
      "description": "被动技能体系。包括自动回复咒力、对带有咒印的敌人增加伤害，以及在受到致命攻击时进入无敌瞬身状态并回复生命值的保命能力。"
    }
  ]
}

