      "nature": "现任上司/同伴",
      "description": "目前德尔塔跟随舰长及休伯利安一行人，将以太锚点归还给各个世界泡。"
    },
    "八重霞": {
      "nature": "同事",
      "description": "同属摆渡人麾下的同事，曾在盛夏海滨游乐园事件中奉命带走失去自我的德尔塔。"
