    "希儿": {
      "nature": "临时旅伴",
      "description": "在崩坏冒险谭中偶遇的“勇者”。德尔塔虽然觉得她有些麻烦，但还是带着她一路前进，并在最后尊重了希儿的愿望，替她解决了魔王。"
    }
  }
}

