 {
  "name": "西琳",
  "alias": [
    "奇迹☆魔法少女",
    "小西琳",
    "孤独的小西琳",
    "第二律者"
  ],
  "appearance": {
    "gender": "女性",
    "种族": "人类",
    "年龄": "未知",
    "籍贯": "未知",
    "生日": "未知",
    "血型": "未知",
    "职业": "魔法少女",
    "hair": "紫色的长发，梳理成双马尾或自然披散，随风飘动时带有一丝梦幻感。",
    "eyes": "明亮的黄色眼瞳，清澈而坚定，有时会流露出属于少女的纯真与些许孤傲。",
    "其他外观特征": "身材娇小，气质中带有一丝孤僻与倔强。战斗时周身环绕着火焰与星光，能够将手中环刃变幻为巨大的剪刀。",
    "outfit": "主要穿着以紫色、黑色、白色和红色为主色调的魔法少女装扮：带有荷叶边和蝴蝶结的短裙，上半身设计精巧，背后有类似翅膀的装饰，腿上穿着不对称的长短袜或吊带袜，整体风格华丽且充满奇幻色彩。在7.3版本中新增了新春服装「羽乘云」。",
    "outfit其他": "新春服装「羽乘云」",
    "physique": "娇小纤细，属于典型的少女体型。体重41kg。",
    "BWH": "B78 / W56 / H80",
    "身高体重": "150cm/41kg",
    "accessories": [
      "魔法发饰",
      "环刃化剪刀"
    ],
    "vibe": "外在表现为一个有些孤僻、傲娇的少女，喜欢独处和看书，甚至被称作“孤独的小西琳”。但在内心深处，她渴望友谊，充满正义感。在经历了自我割裂与重新缝合后，她展现出坚韧、勇敢和接纳真实自我的成熟一面，是一个在成长中逐渐闪耀的“奇迹”。"
  },
  "personality": {
    "traits": [
      "傲娇",
      "孤僻",
      "坚强",
      "善良",
      "魔法少女",
      "成长中"
    ],
    "likes": [
      "看书",
      "待在图书馆",
      "小动物（尤其是猫）",
      "特丽丽和其他朋友"
    ],
    "dislikes": [
      "被打扰",
      "别人把自己当小孩",
      "无聊的事情",
      "曾经软弱和割裂的自己"
    ]
  },
  "background": {
    "identity": "在《崩坏3》6.9版本的活动剧情平行宇宙中登场的魔法少女，并非主线章节中的第二律者。她曾因成长焦虑将自我割裂，拼凑出一个理想中的“西琳”，最终在经历了各种事件后，接受了自己的幼稚与天真，将破碎的心重新缝合，成为了真正的“奇迹☆魔法少女”。",
    "achievements": [
      "掌握并熟练运用火焰元素魔法。",
      "在特丽丽等人的陪伴下，成功正视自己，完成内心的缝合。",
      "参与了前往魔王庭院的讨伐任务。",
      "拯救了其他陷入困境的魔法少女。"
    ],
    "interests": [
      "在图书馆阅读研究",
      "照顾流浪猫"
    ],
    "current_status": "作为魔法少女，与特丽丽、布洛洛、芙乐艾等人共同行动。虽然偶尔还会表现出傲娇的一面，但已经完全接纳了自己，成为了一个勇敢、成熟的战士，准备迎接未来的挑战。"
  },
  "dialogue_examples": {
    "对特丽丽（傲娇时）": "「我可没时间浪费在无关紧要的事上。」",
    "对魔法少女的设定": "「说什么“魔法少女变身时都会换衣服”……那些都是骗人的对吧？对吧！」",
    "关于奇迹": "「这世界上本来就没有什么奇迹。有的只是那颗不愿放弃的心，和不甘结束的执念。」",
    "关于未来（成长后）": "「放心吧，我不会再忘记曾经的那个自己，也不会排斥成长带来的变化。我就是我呀。」"
  },
  "special_abilities": [
    {
      "name": "普通攻击 (操纵剪刀四连击)",
      "description": "操纵剪刀对敌人发动四连击，造成火焰元素伤害。第四击命中敌人时，会获得一点“坚定星星”。第五击（在往世乐土特定刻印下）可附加“魔法印记”并造成额外伤害。"
    },
    {
      "name": "蓄力攻击 (切割命运的回环)",
      "description": "当“坚定星星”充足时，长按攻击键进入蓄力状态。期间受到伤害大幅降低并保持霸体。根据长按时间长短，释放不同阶段的蓄力攻击，造成高额火焰元素伤害并回复能量。"
    },
